// Word document defaults used by LibreOffice import/export are 11pt text,
// 0.5in tab stops, and widow/orphan control of two lines.
const PARAGRAPH_SPACING_AFTER_PT: f32 = 0.0;
const DEFAULT_TAB_STOP_PT: f32 = 36.0;
// Without an explicit w:defaultTabStop, Word recovers a separate 420-twip
// application grid for literal U+0009 characters preserved inside w:t.
// Import maps a literal tab to this marker only on that omitted-setting path.
const PRESERVED_WORD_TEXT_TAB_STOP_PT: f32 = 21.0;
const DEFAULT_FONT_SIZE_PT: f32 = 11.0;
const DEFAULT_LINE_HEIGHT_PT: f32 = 14.0;
// Word's Global::LinesToPoints contract defines one line as 12 points, and
// LibreOffice imports w:beforeLines/w:afterLines with the same 240-twip
// nSingleLineSpacing value in writerfilter::DomainMapper. This paragraph-
// spacing unit is independent of the section document grid, which owns the
// pitch of lines inside a paragraph.
const WORD_PARAGRAPH_LINE_UNIT_PT: f32 = 240.0 / units::TWIPS_PER_POINT;
// Writer frame size, including table rows.
const LO_MIN_FRAME_SIZE_PT: f32 = 23.0 / units::TWIPS_PER_POINT;
const TABLE_ROW_MIN_HEIGHT_PT: f32 = LO_MIN_FRAME_SIZE_PT;
const COLLAPSED_EMPTY_CELL_PARAGRAPH_HEIGHT_PT: f32 = 1.0 / units::TWIPS_PER_POINT;
const TABLE_SPACING_AFTER_PT: f32 = 0.0;
const DEFAULT_ORPHAN_LINES: usize = 2;
const DEFAULT_WIDOW_LINES: usize = 2;
const MAX_HYPHENATION_BOTTOM_REFLOWS: u8 = 32;
const MOVE_BACKWARD_SUPPRESS_THRESHOLD: usize = 20;
const LAYOUT_LOOP_CONTROL_MAX: usize = 10_000;
const UNBOUNDED_LAYOUT_EXTENT_PT: f32 = f32::MAX / 4.0;
const MEASURE_SCRATCH_PAGE_HEIGHT_PT: f32 = UNBOUNDED_LAYOUT_EXTENT_PT;
const LAYOUT_EPSILON_PT: f32 = 0.1;
// sets OOXML document defaults to proportional line spacing 115.
const LO_DOCUMENT_DEFAULT_LINE_SPACING_PERCENT: f32 = 115.0;
const PERCENT_SCALE: f32 = 100.0;
const LO_EMPTY_PARAGRAPH_FIRST_LINE_HEIGHT_PER_FONT_SIZE: f32 = 340.0 / 220.0;
const LO_DRAWING_ANCHOR_MARGIN_LINE_HEIGHT_PT: f32 = 288.0 / units::TWIPS_PER_POINT;
// Word extends a paragraph decoration box beyond its text frame before
// applying w:pBdr/@space and the border stroke. Keep decoration paint and
// paragraph-frame wrap geometry on the same sourced boundary.
const WORD_PARAGRAPH_DECORATION_HORIZONTAL_PADDING_PT: f32 = 1.5;
// Word fixed-format output uses a two-inch separator for ordinary footnotes
// and endnotes. SwPageFootnoteInfo supplies the 10-twip line width and
// 57-twip top/bottom distances used by the footnote layout path.
const WORD_NOTE_SEPARATOR_WIDTH_PT: f32 = 2.0 * units::POINTS_PER_INCH;
const WORD_NOTE_SEPARATOR_STROKE_PT: f32 = 0.72;
const LO_FOOTNOTE_SEPARATOR_STROKE_PT: f32 = 10.0 / units::TWIPS_PER_POINT;
const LO_FOOTNOTE_SEPARATOR_TOP_DIST_PT: f32 = 57.0 / units::TWIPS_PER_POINT;
const LO_FOOTNOTE_SEPARATOR_BOTTOM_DIST_PT: f32 = 57.0 / units::TWIPS_PER_POINT;
const LO_PLACEHOLDER_FLOATING_LINE_HEIGHT_PER_FONT_SIZE: f32 = 0.484;
const WORD_LEGACY_OUTLINE_WIDTH_PT: f32 = 0.14;
const WORD_LEGACY_RELIEF_OFFSET_PT: f32 = 0.96;
const WORD_FIXED_OUTPUT_DPI: f32 = 600.0;
// Word's fixed-output text-effect images retain a transparent 10-DIP guard
// outside the filter output. The six independent glow/shadow/reflection
// XObjects in TextEffects_Glow_Shadow_Reflection.docx preserve about 20 pixels
// at 200 DPI and 10 pixels at 100 DPI, including the two opposite blur-size
// counterexamples. This guard belongs to raster materialization, not to the
// authored DrawingML radius or alignment rectangle.
const WORD_TEXT_EFFECT_RASTER_GUARD_PT: f32 = 10.0 * 72.0 / 96.0;
const WORD_STATIC_3D_RASTER_EDGE_GUARD_PT: f32 = 72.0 / 200.0;
// Internal transport tag for a Word-generated static-3D/effect render target.
// The bytes remain PNG so layout consumers can decode them normally; the PDF
// writer uses the tag to apply Word's fixed-output JPEG color-plane policy.
const WORD_STATIC_3D_BITMAP_CONTENT_TYPE: &str =
  "application/vnd.ooxmlsdk.wordprocessing-static-3d+png";
// Word fixed output snaps the legacy field glyph to its 600-DPI printer grid.
// The independent 10-point Arial (checkboxes.docx), 11-point Calibri
// (n766477.docx), and colored 10-point Open Sans fallback (tdf92472.docx)
// counterexamples agree on these grid widths while retaining different
// font-metric portion sizes and the authored run color.
const WORD_LEGACY_FORM_CHECK_BOX_OUTER_INSET_DOTS: f32 = 6.5;
const WORD_LEGACY_FORM_CHECK_BOX_BORDER_DOTS: f32 = 6.0;
const WORD_LEGACY_FORM_CHECK_BOX_MARK_DOTS: f32 = 4.0;
const WORD_LEGACY_FORM_CHECK_BOX_MARK_OVERHANG_DOTS: f32 = 1.0;
const WORD_LEGACY_SHADOW_OFFSET_PER_FONT_SIZE: f32 = 0.04;
const WORD_LEGACY_EFFECT_BLACK: RgbColor = RgbColor { r: 0, g: 0, b: 0 };
const WORD_LEGACY_EFFECT_GRAY: RgbColor = RgbColor {
  r: 0x99,
  g: 0x99,
  b: 0x99,
};
const WORD_LEGACY_SHADOW_GRAY: RgbColor = RgbColor {
  r: 0xc0,
  g: 0xc0,
  b: 0xc0,
};

#[derive(Clone, Copy, Debug)]
enum NoteSeparatorKind {
  Footnote,
  Endnote,
  EndnoteContinuation,
}

fn inline_text_height(style: &TextStyle, text_metrics: &mut TextMetrics) -> f32 {
  text_metrics
    .line_vertical_metrics(style)
    .line_height_pt()
    .max(style.line_height_override_pt.unwrap_or_default())
}

#[derive(Clone, Copy, Debug, Default)]
struct WordLineTextExtents {
  ascent_pt: f32,
  descent_pt: f32,
  minimum_height_pt: f32,
  has_text: bool,
  has_intrinsic_leading_above: bool,
}

impl WordLineTextExtents {
  fn include(
    &mut self,
    style: &TextStyle,
    text: &str,
    script_sensitive_line_height: bool,
    text_metrics: &mut TextMetrics,
  ) {
    let metrics = if script_sensitive_line_height {
      text_metrics.line_vertical_metrics_for_text(text, style)
    } else {
      text_metrics.line_vertical_metrics(style)
    };
    self.has_text = true;
    self.has_intrinsic_leading_above |= metrics.leading_above_pt() > LAYOUT_EPSILON_PT;
    // Application-generated resource text can carry a line box which is
    // taller than the selected face's intrinsic ascent/descent. Preserve that
    // per-portion minimum while combining a mixed line: DirectWrite's default
    // line-spacing mode and Writer's SwLineLayout::CalcLine both let the
    // tallest item determine the line height. Keeping it separate from the
    // natural ascent/descent also leaves baseline ownership to TextFrame's
    // generated-resource cap.
    self.minimum_height_pt = self
      .minimum_height_pt
      .max(style.line_height_override_pt.unwrap_or_default());
    // ECMA-376 Part 1 §17.3.2.24 positions the run relative to the
    // surrounding unpositioned baseline. IDWriteTextLayout's default line
    // metrics place that baseline at ascent + derived line gap and retain the
    // complete ascent + descent + gap height. A signed w:position therefore
    // redistributes that natural box above and below the common baseline; it
    // does not independently append abs(position) to every run's height.
    let default_baseline_pt = if style.use_windows_font_metrics {
      metrics.directwrite_baseline_offset_pt
    } else {
      metrics.leading_above_pt() + metrics.ascent_pt
    };
    // Automatic w:vertAlign paints a reduced glyph inside the original-font
    // line box. Its paint shift must not move that box's common baseline;
    // manual w:position, on the other hand, redistributes the line extents.
    let line_shift_pt = if style.automatic_escapement_font_size_pt.is_some() {
      0.0
    } else {
      style.baseline_shift_pt
    };
    self.ascent_pt = self
      .ascent_pt
      .max((default_baseline_pt + line_shift_pt).max(0.0));
    self.descent_pt = self
      .descent_pt
      .max((metrics.line_height_pt() - default_baseline_pt - line_shift_pt).max(0.0));
  }

  fn height_pt(self) -> f32 {
    (self.ascent_pt + self.descent_pt).max(self.minimum_height_pt)
  }

  fn uses_typographic_gap_below_baseline(self) -> bool {
    self.has_text && !self.has_intrinsic_leading_above
  }
}

fn paragraph_base_line_style(paragraph: &crate::docx::Paragraph) -> TextStyle {
  if let Some(style) = paragraph.inlines.iter().find_map(|inline| match inline {
    InlineItem::Text(run) if text_run_affects_line_height(&run.text) => Some(run.style.clone()),
    InlineItem::Text(_) => None,
    InlineItem::NoteReferenceMark(_) => None,
    InlineItem::NoteSeparatorMark(mark) => Some(mark.style.clone()),
    InlineItem::ClearLineBreak(_) => None,
    InlineItem::PositionalTab(_) => None,
    InlineItem::Ruby(ruby) => ruby.base.first().map(|run| run.style.clone()),
    InlineItem::LegacyFormCheckBox(check_box) => Some(check_box.style.clone()),
    InlineItem::Image(_)
    | InlineItem::Shape(_)
    | InlineItem::DrawingGroupStart(_)
    | InlineItem::DrawingGroupEnd
    | InlineItem::BookmarkStart(_)
    | InlineItem::FormWidgetStart(_)
    | InlineItem::FormWidgetEnd(_)
    | InlineItem::LastRenderedPageBreak
    | InlineItem::PageBreak
    | InlineItem::ColumnBreak => None,
  }) {
    return style;
  }

  paragraph_ignored_blank_line_style(paragraph).unwrap_or_else(|| paragraph.base_style.clone())
}

fn text_run_affects_line_height(text: &str) -> bool {
  text
    .chars()
    .any(|ch| ch != '\n' && ch != '\t' && !libreoffice_ignored_line_height_blank(ch))
}

fn paragraph_ignored_blank_line_style(paragraph: &crate::docx::Paragraph) -> Option<TextStyle> {
  let mut style = paragraph.base_style.clone();
  style.font_size_pt = TextStyle::default().font_size_pt;
  let mut found = false;
  for inline in &paragraph.inlines {
    let InlineItem::Text(run) = inline else {
      continue;
    };
    if text_run_affects_line_height(&run.text) {
      continue;
    }
    if !found || run.style.font_size_pt < style.font_size_pt {
      style.font_size_pt = run.style.font_size_pt;
    }
    found = true;
  }
  found.then_some(style)
}

fn paragraph_line_height_for_setup(
  paragraph: &crate::docx::Paragraph,
  base_line_style: &TextStyle,
  setup: PageSetup,
  text_segmentation: TextSegmentation,
  text_metrics: &mut TextMetrics,
) -> f32 {
  match paragraph.format.line_height_rule {
    LineHeightRule::Auto => {
      // ECMA-376 §17.3.1.33 defines an auto `w:line` value in 240ths of
      // the normal single line height. Use the resolved face metrics for that
      // single-line basis; 115% of the nominal font size is only Writer's
      // compatibility approximation and can differ from Word's font height.
      let single_line_height =
        paragraph_single_line_height(paragraph, base_line_style, text_metrics);
      let line_height = paragraph
        .format
        .line_height_pt
        .map_or(single_line_height, |multiple| single_line_height * multiple);
      grid_auto_line_heights(
        paragraph,
        base_line_style,
        setup,
        text_segmentation,
        text_metrics,
      )
      .map_or(line_height, |heights| heights.first_line_pt)
    }
    LineHeightRule::AtLeast => {
      let natural_line_height = inline_text_height(base_line_style, text_metrics);
      document_grid_line_metrics(natural_line_height, paragraph, setup, text_segmentation)
        .map_or_else(
          || {
            paragraph
              .format
              .line_height_pt
              .map_or(natural_line_height, |minimum| {
                natural_line_height.max(minimum)
              })
          },
          |metrics| metrics.height_pt,
        )
    }
    LineHeightRule::Exact => paragraph
      .format
      .line_height_pt
      .unwrap_or_else(|| inline_text_height(base_line_style, text_metrics)),
  }
}

#[derive(Clone, Copy, Debug)]
struct GridAutoLineHeights {
  first_line_pt: f32,
  following_line_pt: f32,
}

fn grid_auto_line_heights(
  paragraph: &crate::docx::Paragraph,
  base_line_style: &TextStyle,
  setup: PageSetup,
  text_segmentation: TextSegmentation,
  text_metrics: &mut TextMetrics,
) -> Option<GridAutoLineHeights> {
  if !matches!(paragraph.format.line_height_rule, LineHeightRule::Auto)
    || !paragraph.format.snap_to_grid.unwrap_or(true)
    || !text_segment_uses_document_grid(text_segmentation, setup)
  {
    return None;
  }
  let grid_height = setup.doc_grid_line_pitch_pt?;
  let visible_line_height = inline_text_height(base_line_style, text_metrics);
  let snapped_line_height = snap_line_height_to_doc_grid(visible_line_height, Some(grid_height));
  let proportional_line_height = paragraph
    .format
    .line_height_pt
    .map_or(grid_height, |multiple| grid_height * multiple.max(1.0));

  // Writer's LINE_SPACING_AS_GAP_BELOW path and Office fixed output keep a
  // one-grid first line at the grid height, then place the proportional
  // excess below it. When the visible font already spans multiple grid rows,
  // however, Word applies the independently computed proportional grid height
  // to that first line as well. TOC2's 22pt Heading 1 is the latter case:
  // max(31.2pt snapped text, 15.6pt * 578/240) = 37.57pt.
  let first_line_pt = if snapped_line_height > grid_height + LAYOUT_EPSILON_PT {
    snapped_line_height.max(proportional_line_height)
  } else {
    snapped_line_height
  };

  Some(GridAutoLineHeights {
    first_line_pt,
    // Do not multiply the already-snapped visible height. The authored auto
    // multiple and the number of grid rows are independent lower bounds.
    following_line_pt: snapped_line_height.max(proportional_line_height),
  })
}

fn paragraph_single_line_height(
  paragraph: &crate::docx::Paragraph,
  base_line_style: &TextStyle,
  text_metrics: &mut TextMetrics,
) -> f32 {
  let visible_text_height = paragraph
    .inlines
    .iter()
    .find_map(|inline| match inline {
      InlineItem::Text(run) if text_run_affects_line_height(&run.text) => Some(
        inline_text_height_for_text(&run.style, &run.text, text_metrics),
      ),
      _ => None,
    })
    .unwrap_or_else(|| inline_text_height(base_line_style, text_metrics));

  if !paragraph.format.justification.is_block() {
    return visible_text_height;
  }

  // ECMA-376 Part 1 §17.3.3.1 defines w:br as a special character in the
  // current run's content. Word's legacy fully-justified Shift+Return path
  // therefore keeps the run's composite font-slot line box, even when the
  // visible text in that run is Latin. Limit that behavior to the run which
  // actually owns a text-wrapping break; automatic wraps remain driven by
  // their visible-script metrics.
  paragraph
    .inlines
    .iter()
    .filter_map(|inline| {
      let InlineItem::Text(run) = inline else {
        return None;
      };
      run.text.contains('\n').then(|| {
        let metrics =
          text_metrics.vertical_metrics_for_script(&run.style, ooxmlsdk_fonts::TextScript::Han);
        metrics.line_height_pt() + run.style.baseline_shift_pt.abs()
      })
    })
    .fold(visible_text_height, f32::max)
}

fn paragraph_has_automatic_superscript(paragraph: &crate::docx::Paragraph) -> bool {
  let paragraph_size = paragraph.base_style.font_size_pt;
  paragraph.inlines.iter().any(|inline| {
    let InlineItem::Text(run) = inline else {
      return false;
    };
    text_run_affects_line_height(&run.text)
      && run.style.baseline_shift_pt > 0.0
      && run.style.font_size_pt < paragraph_size - LAYOUT_EPSILON_PT
  })
}

fn word_east_asian_paragraph_mark_single_line_height(
  paragraph: &crate::docx::Paragraph,
  compatibility_mode: u16,
  prior_line_count: usize,
  text_metrics: &mut TextMetrics,
) -> Option<f32> {
  let uses_east_asian_paragraph_mark = if compatibility_mode >= 15 {
    paragraph.format.justification.adjust == crate::docx::ParagraphAdjust::Start
  } else {
    paragraph.format.justification.adjust == crate::docx::ParagraphAdjust::Left
      && paragraph_has_automatic_superscript(paragraph)
  };
  if prior_line_count != 0
    || !uses_east_asian_paragraph_mark
    || !matches!(paragraph.format.line_height_rule, LineHeightRule::Auto)
    || paragraph.format.line_height_pt.is_some()
  {
    return None;
  }

  // MS-OI29500 §17.3.2.26 still selects the ascii face for Basic Latin glyphs.
  // Word nevertheless sizes the implicit paragraph-mark box from the
  // paragraph's East Asian face for compatibility-mode-15 logical-start text
  // and for a legacy mixed ordinary/automatic-superscript line. Office fixed
  // output keeps the Latin glyphs in Liberation Serif while its 17.28pt
  // baseline step matches the 17.244pt Noto Serif CJK SC line box. The
  // superscript itself uses the Latin face's OS/2 superscript size and offset;
  // its presence is the legacy paragraph-mark trigger, not a request to shape
  // the visible Latin text with the East Asian face.
  // Keep wrapped lines on their visible-script metrics and preserve the
  // legacy physical-left path used by older compatibility documents.
  let metrics = text_metrics
    .vertical_metrics_for_script(&paragraph.base_style, ooxmlsdk_fonts::TextScript::Han);
  let line_height = metrics.line_height_pt();
  (line_height > 0.0).then_some(line_height)
}

fn paragraph_uses_only_paragraph_mark_baseline_shift(paragraph: &crate::docx::Paragraph) -> bool {
  let paragraph_shift = paragraph.base_style.baseline_shift_pt;
  if paragraph_shift.abs() <= f32::EPSILON {
    return false;
  }
  let mut saw_text = false;
  for inline in &paragraph.inlines {
    match inline {
      InlineItem::Text(run) if text_run_affects_line_height(&run.text) => {
        if (run.style.baseline_shift_pt - paragraph_shift).abs() > LAYOUT_EPSILON_PT {
          return false;
        }
        saw_text = true;
      }
      InlineItem::Text(_) | InlineItem::BookmarkStart(_) => {}
      _ => return false,
    }
  }
  saw_text
}

fn paragraph_uses_only_translucent_glyph_paths(paragraph: &crate::docx::Paragraph) -> bool {
  let mut saw_text = false;
  for inline in &paragraph.inlines {
    match inline {
      InlineItem::Text(run) if text_run_affects_line_height(&run.text) => {
        if run.style.semantic_only
          || run.style.opacity <= f32::EPSILON
          || run.style.opacity >= 1.0 - f32::EPSILON
        {
          return false;
        }
        saw_text = true;
      }
      InlineItem::Text(_) | InlineItem::BookmarkStart(_) => {}
      _ => return false,
    }
  }
  saw_text
}

fn paragraph_auto_baseline_line_height_cap(
  paragraph: &crate::docx::Paragraph,
  base_line_style: &TextStyle,
  text_metrics: &mut TextMetrics,
) -> Option<f32> {
  matches!(paragraph.format.line_height_rule, LineHeightRule::Auto).then(|| {
    // Writer's LINE_SPACING_AS_GAP_BELOW compatibility path leaves the first
    // line's glyph baseline in the ordinary line box and owns proportional
    // excess below the text. Office fixed output does the same: even an
    // extreme auto multiple keeps the first baseline at the default 115%
    // position while the full real height still drives following flow.
    paragraph_single_line_height(paragraph, base_line_style, text_metrics)
      * LO_DOCUMENT_DEFAULT_LINE_SPACING_PERCENT
      / PERCENT_SCALE
  })
}

fn doc_grid_character_pitch(
  paragraph: &crate::docx::Paragraph,
  setup: PageSetup,
  text_segmentation: TextSegmentation,
) -> Option<f32> {
  if !paragraph.format.snap_to_grid.unwrap_or(true)
    || !text_segment_uses_document_grid(text_segmentation, setup)
  {
    return None;
  }
  setup.doc_grid_character_spacing_pt.map(|spacing| {
    (paragraph_base_line_style(paragraph).font_size_pt + spacing).max(LAYOUT_EPSILON_PT)
  })
}

fn grid_character_segment_width(text: &str, pitch_pt: Option<f32>) -> Option<f32> {
  let pitch_pt = pitch_pt?;
  let count = text.chars().count();
  (count > 0 && text.chars().all(cjk_line_character)).then_some(pitch_pt * count as f32)
}

fn text_segment_uses_document_grid(text_segmentation: TextSegmentation, setup: PageSetup) -> bool {
  matches!(text_segmentation, TextSegmentation::Body)
    || (matches!(text_segmentation, TextSegmentation::TableCell)
      && setup.adjust_table_line_heights_to_grid)
}

fn snap_line_height_to_doc_grid(line_height: f32, doc_grid_line_pitch_pt: Option<f32>) -> f32 {
  let Some(grid_height) = doc_grid_line_pitch_pt else {
    return line_height;
  };
  if grid_height <= LAYOUT_EPSILON_PT || line_height <= grid_height {
    return line_height.max(grid_height);
  }
  // SwTextFormatter::CalcRealHeight() rounds a snapped line up to the next
  // document-grid base-height multiple.
  (line_height / grid_height).ceil() * grid_height
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct DocumentGridLineMetrics {
  height_pt: f32,
  ascent_adjustment_pt: f32,
}

fn document_grid_line_metrics(
  source_line_height_pt: f32,
  paragraph: &crate::docx::Paragraph,
  setup: PageSetup,
  text_segmentation: TextSegmentation,
) -> Option<DocumentGridLineMetrics> {
  if !paragraph.format.snap_to_grid.unwrap_or(true)
    || !text_segment_uses_document_grid(text_segmentation, setup)
  {
    return None;
  }
  let grid_height_pt = setup.doc_grid_line_pitch_pt?;

  // ECMA-376 Part 1 §§17.3.1.32 and 17.6.5 make the current line use the
  // section's document-grid pitch. Writer's SwTextFormatter::CalcRealHeight()
  // first rounds the complete source line to that pitch, then implements the
  // full tdf#164871 rule family: atLeast=0 disables the grid extra, a nonzero
  // atLeast value remains a lower bound, and exact replaces the snapped
  // height. It then centers the height delta in the line ascent; the delta is
  // intentionally negative when an exact line is shorter than its content.
  // UpdatePos() consumes that adjusted ascent when it resets an as-character
  // fly or graphic-number base.
  let snapped_height_pt = snap_line_height_to_doc_grid(source_line_height_pt, Some(grid_height_pt));
  let height_pt = match paragraph.format.line_height_rule {
    LineHeightRule::Auto => snapped_height_pt,
    LineHeightRule::AtLeast => match paragraph.format.line_height_pt {
      Some(minimum_height_pt) if minimum_height_pt <= LAYOUT_EPSILON_PT => source_line_height_pt,
      Some(minimum_height_pt) => snapped_height_pt.max(minimum_height_pt),
      None => snapped_height_pt,
    },
    LineHeightRule::Exact => paragraph
      .format
      .line_height_pt
      .unwrap_or(source_line_height_pt),
  };
  Some(DocumentGridLineMetrics {
    height_pt,
    ascent_adjustment_pt: (height_pt - source_line_height_pt) / 2.0,
  })
}

fn inline_object_line_metrics_for_flow(
  source_line_height_pt: f32,
  paragraph: &crate::docx::Paragraph,
  flow: FlowContext,
) -> DocumentGridLineMetrics {
  document_grid_line_metrics(
    source_line_height_pt,
    paragraph,
    flow.setup,
    flow.text_segmentation,
  )
  .unwrap_or(DocumentGridLineMetrics {
    height_pt: source_line_height_pt,
    ascent_adjustment_pt: 0.0,
  })
}

fn word_auto_line_height(style: &TextStyle) -> f32 {
  effective_font_size_pt(style, None) * LO_DOCUMENT_DEFAULT_LINE_SPACING_PERCENT / PERCENT_SCALE
}

fn libreoffice_empty_paragraph_first_line_height(style: &TextStyle) -> f32 {
  // first-line box that is taller than the default 115% auto line height.
  effective_font_size_pt(style, None) * LO_EMPTY_PARAGRAPH_FIRST_LINE_HEIGHT_PER_FONT_SIZE
}

fn include_text_height(
  line_height: f32,
  paragraph: &crate::docx::Paragraph,
  flow: FlowContext,
  text_frame: TextFrame,
  line_text_extents: &mut WordLineTextExtents,
  style: &TextStyle,
  text: &str,
  text_metrics: &mut TextMetrics,
) -> f32 {
  line_text_extents.include(
    style,
    text,
    text_frame.script_sensitive_line_height,
    text_metrics,
  );
  let text_height = line_text_extents.height_pt();
  let text_height =
    document_grid_line_metrics(text_height, paragraph, flow.setup, flow.text_segmentation)
      .map_or(text_height, |metrics| metrics.height_pt);
  let text_height = proportional_auto_text_line_height(text_height, paragraph, flow);
  match text_frame.line_height_rule {
    LineHeightRule::Exact => line_height,
    LineHeightRule::Auto | LineHeightRule::AtLeast => line_height.max(text_height),
  }
}

fn at_least_uses_separate_content_height(
  paragraph: &crate::docx::Paragraph,
  flow: FlowContext,
) -> bool {
  matches!(paragraph.format.line_height_rule, LineHeightRule::AtLeast)
    && document_grid_line_metrics(1.0, paragraph, flow.setup, flow.text_segmentation).is_none()
}

fn proportional_auto_line_spacing_gap_below(
  paragraph: &crate::docx::Paragraph,
  flow: FlowContext,
  base_line_style: &TextStyle,
  base_line_height: f32,
  text_metrics: &mut TextMetrics,
) -> f32 {
  if !matches!(paragraph.format.line_height_rule, LineHeightRule::Auto)
    || !paragraph
      .format
      .line_height_pt
      .is_some_and(|multiple| multiple > 1.0)
    || document_grid_line_metrics(1.0, paragraph, flow.setup, flow.text_segmentation).is_some()
  {
    return 0.0;
  }

  // ECMA-376 Part 1 §17.3.1.33 defines an auto value as spacing *between*
  // lines. Writer's Word-compatible LINE_SPACING_AS_GAP_BELOW path models
  // the proportional excess as a gap owned after the visible line. Keep that
  // gap in the flow advance, but not in the height which must fit at the
  // bottom of the current flow slot. Document-grid rows have their own
  // snapped first/following-line model and intentionally stay out of this
  // non-grid split.
  let natural_line_height = paragraph_single_line_height(paragraph, base_line_style, text_metrics);
  (base_line_height - natural_line_height).max(0.0)
}

fn proportional_auto_text_line_spacing_multiple(
  paragraph: &crate::docx::Paragraph,
  flow: FlowContext,
) -> Option<f32> {
  if !matches!(paragraph.format.line_height_rule, LineHeightRule::Auto)
    || document_grid_line_metrics(1.0, paragraph, flow.setup, flow.text_segmentation).is_some()
    || !paragraph_line_spacing_base_covers_line_height(paragraph)
  {
    return None;
  }
  paragraph
    .format
    .line_height_pt
    .filter(|multiple| multiple.is_finite() && *multiple > 0.0)
}

fn proportional_auto_baseline_uses_text_line_spacing(
  paragraph: &crate::docx::Paragraph,
  multiple: Option<f32>,
  allows_gap_below: bool,
) -> bool {
  allows_gap_below
    && (paragraph.format.line_height_set
      || (paragraph
        .format
        .wordprocessing_shape_compatible_line_spacing
        && multiple.is_some_and(|multiple| {
          multiple > LO_DOCUMENT_DEFAULT_LINE_SPACING_PERCENT / PERCENT_SCALE
        })))
}

fn paragraph_line_spacing_base_covers_line_height(paragraph: &crate::docx::Paragraph) -> bool {
  if paragraph.list_label.is_some() || paragraph.list_label_image.is_some() {
    return false;
  }
  paragraph.inlines.iter().all(|inline| {
    matches!(
      inline,
      InlineItem::Text(_)
        | InlineItem::ClearLineBreak(_)
        | InlineItem::PositionalTab(_)
        | InlineItem::Ruby(_)
        | InlineItem::BookmarkStart(_)
        | InlineItem::FormWidgetStart(_)
        | InlineItem::FormWidgetEnd(_)
        | InlineItem::LastRenderedPageBreak
        | InlineItem::PageBreak
        | InlineItem::ColumnBreak
    )
  })
}

fn proportional_auto_text_line_height(
  natural_height: f32,
  paragraph: &crate::docx::Paragraph,
  flow: FlowContext,
) -> f32 {
  proportional_auto_text_line_spacing_multiple(paragraph, flow)
    .map_or(natural_height, |multiple| natural_height * multiple)
}

fn include_text_content_height(
  content_height: f32,
  paragraph: &crate::docx::Paragraph,
  flow: FlowContext,
  text_frame: TextFrame,
  line_text_extents: &mut WordLineTextExtents,
  style: &TextStyle,
  text: &str,
  text_metrics: &mut TextMetrics,
) -> f32 {
  if !at_least_uses_separate_content_height(paragraph, flow) {
    return content_height;
  }
  line_text_extents.include(
    style,
    text,
    text_frame.script_sensitive_line_height,
    text_metrics,
  );
  content_height.max(line_text_extents.height_pt())
}

fn include_numbering_label_height(
  paragraph: &crate::docx::Paragraph,
  line_height: f32,
  flow: FlowContext,
  text_frame: TextFrame,
  line_text_extents: &mut WordLineTextExtents,
  text_metrics: &mut TextMetrics,
) -> f32 {
  let Some(label) = paragraph.list_label.as_deref() else {
    return line_height;
  };
  if label.chars().all(char::is_whitespace) {
    return line_height;
  }
  let visible_label = label
    .strip_suffix('\t')
    .or_else(|| label.strip_suffix(' '))
    .unwrap_or(label);
  if !segment_affects_line_height(visible_label) {
    return line_height;
  }

  // Writer creates numbering as a SwNumberPortion with its own font.
  // SwTextFormatter::CalcAscent() measures that font's height/ascent and the
  // portion participates in the enclosing SwLineLayout just like ordinary
  // text. Keep that ownership here instead of deriving every numbered line
  // from the first printable body run.
  include_text_height(
    line_height,
    paragraph,
    flow,
    text_frame,
    line_text_extents,
    &paragraph.list_label_style,
    visible_label,
    text_metrics,
  )
}

fn numbering_label_origin_pt(
  anchor_x_pt: f32,
  width_pt: f32,
  justification: w::LevelJustificationValues,
  paragraph_bidi: bool,
) -> f32 {
  match justification {
    w::LevelJustificationValues::Left => anchor_x_pt,
    w::LevelJustificationValues::Center => anchor_x_pt - width_pt / 2.0,
    w::LevelJustificationValues::Right => anchor_x_pt - width_pt,
    w::LevelJustificationValues::Start if paragraph_bidi => anchor_x_pt - width_pt,
    w::LevelJustificationValues::Start => anchor_x_pt,
    w::LevelJustificationValues::End if paragraph_bidi => anchor_x_pt,
    w::LevelJustificationValues::End => anchor_x_pt - width_pt,
  }
}

fn update_line_text_height(
  items: &mut [PageItem],
  start_index: usize,
  y: f32,
  line_height_pt: f32,
) {
  for item in items.iter_mut().skip(start_index) {
    match item {
      PageItem::Text(text) if (text.y_pt - y).abs() < 0.01 => {
        text.line_height_pt = text.line_height_pt.max(line_height_pt);
      }
      PageItem::LegacyFormCheckBox(check_box) if (check_box.y_pt - y).abs() < 0.01 => {
        check_box.line_height_pt = check_box.line_height_pt.max(line_height_pt);
      }
      _ => {}
    }
  }
}

fn resolve_at_least_line_content_height(
  items: &mut [PageItem],
  start_index: usize,
  resolved_height_pt: f32,
  content_height_pt: f32,
  paragraph: &crate::docx::Paragraph,
  flow: FlowContext,
) -> bool {
  if flow.text_segmentation == TextSegmentation::TableCell
    || !at_least_uses_separate_content_height(paragraph, flow)
  {
    return false;
  }

  let content_height_pt = content_height_pt
    .max(LAYOUT_EPSILON_PT)
    .min(resolved_height_pt);
  let upper_spacing_pt = (resolved_height_pt - content_height_pt).max(0.0);
  if upper_spacing_pt <= LAYOUT_EPSILON_PT {
    return true;
  }
  let centered_to_bottom_offset_pt = upper_spacing_pt / 2.0;

  // Writer's non-grid SvxLineSpaceRule::Min branch in
  // SwTextFormatter::CalcRealHeight() increases only SwLineLayout::RealHeight;
  // the line's content Height and Ascent remain natural. Paint therefore
  // starts the net content box at `RealHeight - Height`, while the flow cursor
  // still advances by the complete minimum height. Our text items previously
  // used the minimum as their own line box, which split that excess above and
  // below the baseline. Restore the two-level model here after every baseline
  // participant has been measured and aligned.
  for item in items.iter_mut().skip(start_index) {
    match item {
      PageItem::Text(text)
        if (text.line_height_pt - resolved_height_pt).abs() <= LAYOUT_EPSILON_PT =>
      {
        text.y_pt += upper_spacing_pt;
        text.line_height_pt = content_height_pt;
      }
      PageItem::LegacyFormCheckBox(check_box)
        if (check_box.line_height_pt - resolved_height_pt).abs() <= LAYOUT_EPSILON_PT =>
      {
        check_box.y_pt += upper_spacing_pt;
        check_box.line_height_pt = content_height_pt;
      }
      PageItem::FloatingDrawing { .. } => {}
      _ => shift_page_item_y(item, centered_to_bottom_offset_pt),
    }
  }
  true
}

fn inline_drawing_line_height(
  object_height_pt: f32,
  paragraph: &crate::docx::Paragraph,
  text_frame: TextFrame,
  text_metrics: &mut TextMetrics,
) -> f32 {
  if matches!(text_frame.line_height_rule, LineHeightRule::Exact) {
    return object_height_pt;
  }
  let mut proportional_gap = || {
    paragraph
      .format
      .line_height_pt
      .filter(|multiple| *multiple > 1.0)
      .map_or(0.0, |multiple| {
        paragraph_single_line_height(
          paragraph,
          &paragraph_base_line_style(paragraph),
          text_metrics,
        ) * (multiple - 1.0)
      })
  };
  if legacy_inline_object_owns_line_box(paragraph, text_frame) {
    // Writer's SwTextFormatter::InsertPortion() implements
    // MS_WORD_COMP_MIN_LINE_HEIGHT_BY_FLY through compatibility mode 14 by
    // replacing both line ascent and height with the last as-character
    // portion when it is followed only by the zero-length paragraph mark.
    // This applies to every inline fly/drawing, including an imported Math
    // object with an intrinsic baseline, rather than only to chart objects.
    // CalcRealHeight() subsequently owns the proportional spacing below it.
    return object_height_pt + proportional_gap();
  }
  if paragraph_has_only_inline_drawing_content(paragraph)
    && matches!(paragraph.format.line_height_rule, LineHeightRule::Auto)
    && paragraph
      .format
      .line_height_pt
      .is_some_and(|multiple| multiple > 1.0)
  {
    // Writer's LINE_SPACING_AS_GAP_BELOW path keeps proportional auto
    // spacing after an as-character-only line. The fly/drawing owns that
    // line's ascent; the normal text height supplies only the proportional
    // excess, not an additional full font descent. Office fixed output shows
    // the same split for compatibility-mode-15 picture and OLE-only
    // paragraphs in artistic_effects.docx. Text sharing the line, omitted or
    // <=100% auto spacing, and exact/at-least spacing retain the glyph-like
    // paragraph-mark descent below.
    return object_height_pt + proportional_gap();
  }
  // ECMA-376 Part 1 §20.4.2.8 defines an inline drawing as affecting its
  // line like a character glyph of similar size. The object's height is the
  // ascent above the baseline; the paragraph mark still supplies the normal
  // font descent below it. Writer models the same split in
  // SwLineLayout::MaxAscentDescent(), keeping fly-content ascent/descent and
  // ordinary text descent as independent maxima.
  object_height_pt
    + text_metrics
      .vertical_metrics(&paragraph_base_line_style(paragraph))
      .descent_pt
}

fn inline_image_line_height(
  metrics: InlineImageMetrics,
  paragraph: &crate::docx::Paragraph,
  text_frame: TextFrame,
  text_metrics: &mut TextMetrics,
) -> f32 {
  if metrics.line_box == crate::docx::InlineImageLineBox::EmbeddedObjectRunPosition {
    // Equation.3 stores the cached presentation's baseline in the parent
    // run, but Word still measures the preview as an ordinary character-like
    // frame. Reusing OfficeMath's intrinsic-baseline extents here can turn a
    // two-grid preview line into one grid line even though its frame is
    // unchanged.
    return inline_drawing_line_height(
      metrics.frame_height_pt,
      paragraph,
      text_frame,
      text_metrics,
    );
  }
  if metrics.explicit_baseline_gap {
    let extents = inline_image_vertical_extents(metrics);
    let portion_height_pt = extents.ascent_pt + extents.descent_pt;
    if legacy_inline_object_owns_line_box(paragraph, text_frame) {
      if metrics.line_box == crate::docx::InlineImageLineBox::OfficeMathExternal {
        // The OfficeMath host already owns its complete external MATH box.
        return portion_height_pt;
      }
      return inline_drawing_line_height(portion_height_pt, paragraph, text_frame, text_metrics);
    }
    if matches!(text_frame.line_height_rule, LineHeightRule::Exact) {
      // CalcRealHeight() fixes the physical line later.  The unclipped
      // as-character portion still contributes the complete authored
      // ascent/descent so the fixed/grid ascent adjustment is computed from
      // the same source box as Writer's SwFlyCntPortion::SetBase().
      return portion_height_pt;
    }
    let paragraph_descent = text_metrics
      .vertical_metrics(&paragraph_base_line_style(paragraph))
      .descent_pt;
    return extents.ascent_pt + extents.descent_pt.max(paragraph_descent);
  }
  if legacy_inline_object_owns_line_box(paragraph, text_frame) {
    if metrics.line_box == crate::docx::InlineImageLineBox::OfficeMathExternal {
      // Word keeps m:oMathPara inside w:p, but it lays the native OfficeMath
      // zone out from its own external MATH bounds. The legacy Writer import
      // route represents that zone as an as-character fly; applying the
      // generic fly-only proportional gap here would repeat line spacing that
      // `expand_to_open_type_math_line_bounds()` has already resolved.
      // Ordinary pictures/OLE previews stay on inline_drawing_line_height().
      return metrics.frame_height_pt;
    }
    return inline_drawing_line_height(
      metrics.frame_height_pt,
      paragraph,
      text_frame,
      text_metrics,
    );
  }
  if metrics.content_bottom_gap_pt >= 0.0 {
    return inline_drawing_line_height(
      metrics.frame_height_pt,
      paragraph,
      text_frame,
      text_metrics,
    );
  }
  if matches!(text_frame.line_height_rule, LineHeightRule::Exact) {
    return metrics.frame_height_pt;
  }
  let object_descent = -metrics.content_bottom_gap_pt;
  let object_ascent = (metrics.frame_height_pt - object_descent).max(0.0);
  let paragraph_descent = text_metrics
    .vertical_metrics(&paragraph_base_line_style(paragraph))
    .descent_pt;
  object_ascent + object_descent.max(paragraph_descent)
}

fn inline_image_ascent(metrics: InlineImageMetrics) -> f32 {
  if metrics.line_box == crate::docx::InlineImageLineBox::EmbeddedObjectRunPosition {
    return metrics.frame_height_pt;
  }
  if metrics.explicit_baseline_gap {
    return inline_image_vertical_extents(metrics).ascent_pt;
  }
  (metrics.frame_height_pt + metrics.content_bottom_gap_pt.min(0.0)).max(0.0)
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct InlineImageVerticalExtents {
  ascent_pt: f32,
  descent_pt: f32,
}

fn inline_image_vertical_extents(metrics: InlineImageMetrics) -> InlineImageVerticalExtents {
  // An explicit gap is measured from the visible content bottom to the
  // surrounding inline baseline.  Derive both sides from the complete frame
  // geometry so positive w:position grows ascent, negative w:position grows
  // descent, and DrawingML effect extents are counted exactly once.
  let baseline_from_frame_top_pt =
    metrics.content_offset_y_pt + metrics.content_height_pt + metrics.content_bottom_gap_pt;
  InlineImageVerticalExtents {
    ascent_pt: baseline_from_frame_top_pt.max(0.0),
    descent_pt: (metrics.frame_height_pt - baseline_from_frame_top_pt).max(0.0),
  }
}

fn numbering_image_metrics(
  label_image: &crate::docx::ListLabelImage,
  max_width_pt: f32,
  label_style: &TextStyle,
) -> InlineImageMetrics {
  let mut metrics = inline_image_metrics(&label_image.image, max_width_pt);
  // Office fixed output uses the character cell after its approximately
  // two-point internal leading, rather than the font file's Symbol advance
  // (which is only about half an em for U+F0B7 in common Symbol fonts).
  let font_size_pt = effective_font_size_pt(label_style, None);
  let target_height_pt = (font_size_pt - 2.0).max(font_size_pt * 0.5);
  if metrics.frame_height_pt <= LAYOUT_EPSILON_PT || target_height_pt <= LAYOUT_EPSILON_PT {
    return metrics;
  }

  // ISO/IEC 29500-1 §17.9.10 defines the picture as replacing each character
  // in w:lvlText. Word therefore paints it in the replaced character's
  // character cell: its bottom edge is the text baseline. The 14 pt VML
  // import size is only a normalized source box.
  let scale = target_height_pt / metrics.frame_height_pt;
  metrics.frame_width_pt *= scale;
  metrics.frame_height_pt *= scale;
  metrics.content_offset_x_pt *= scale;
  metrics.content_offset_y_pt *= scale;
  metrics.content_width_pt *= scale;
  metrics.content_height_pt *= scale;
  metrics.content_bottom_gap_pt *= scale;
  metrics
}

fn inline_drawing_top(
  line_top_pt: f32,
  object_height_pt: f32,
  paragraph: &crate::docx::Paragraph,
  text_frame: TextFrame,
  text_metrics: &mut TextMetrics,
) -> f32 {
  if matches!(text_frame.line_height_rule, LineHeightRule::Exact) {
    return line_top_pt;
  }
  if legacy_inline_object_owns_line_box(paragraph, text_frame) {
    // The compatibility branch gives the as-character portion its own ascent,
    // so its upper edge is the line top even when that ascent is shorter than
    // the paragraph font's ascent. For Office Math, the portion ascent is the
    // embedded formula's BaseLine property.
    return line_top_pt;
  }
  let base_style = paragraph_base_line_style(paragraph);
  // SwLineLayout::MaxAscentDescent() treats an as-character drawing as one
  // glyph: its ascent is the object's height, while ordinary text supplies
  // the shared fitted baseline.
  let baseline = text_metrics.baseline_offset_in_line(&base_style, text_frame.base_line_height);
  line_top_pt + (baseline - object_height_pt).max(0.0)
}

fn paragraph_has_only_inline_drawing_content(paragraph: &crate::docx::Paragraph) -> bool {
  let mut saw_drawing = false;
  for inline in &paragraph.inlines {
    match inline {
      InlineItem::Image(image)
        if matches!(image.placement, crate::docx::ImagePlacement::Inline) =>
      {
        saw_drawing = true;
      }
      InlineItem::Shape(shape)
        if matches!(shape.placement, crate::docx::ImagePlacement::Inline) =>
      {
        saw_drawing = true;
      }
      InlineItem::Text(run) if run.text.is_empty() => {}
      InlineItem::NoteReferenceMark(_) => {}
      InlineItem::PositionalTab(_) => {}
      InlineItem::DrawingGroupStart(_)
      | InlineItem::DrawingGroupEnd
      | InlineItem::BookmarkStart(_)
      | InlineItem::FormWidgetStart(_)
      | InlineItem::FormWidgetEnd(_)
      | InlineItem::LastRenderedPageBreak => {}
      InlineItem::Text(_)
      | InlineItem::NoteSeparatorMark(_)
      | InlineItem::ClearLineBreak(_)
      | InlineItem::Ruby(_)
      | InlineItem::LegacyFormCheckBox(_)
      | InlineItem::PageBreak
      | InlineItem::ColumnBreak
      | InlineItem::Image(_)
      | InlineItem::Shape(_) => return false,
    }
  }
  saw_drawing
}

fn legacy_inline_object_owns_line_box(
  paragraph: &crate::docx::Paragraph,
  text_frame: TextFrame,
) -> bool {
  text_frame.compatibility_mode < 15 && paragraph_has_only_inline_drawing_content(paragraph)
}

fn word_textbox_inline_drawing_spacing_after(
  paragraph: &crate::docx::Paragraph,
  flow: FlowContext,
  text_frame: TextFrame,
  spacing_after_pt: f32,
  text_metrics: &mut TextMetrics,
) -> f32 {
  if spacing_after_pt <= LAYOUT_EPSILON_PT
    // WPS text stories currently reuse the table-cell formatter but have no
    // physical cell bounds. Keep this rule out of real table cells, whose
    // paragraph spacing participates in row-height measurement.
    || flow.text_segmentation != TextSegmentation::TableCell
    || flow.layout_cell_bounds.is_some()
    || text_frame.compatibility_mode < 15
    || !matches!(text_frame.line_height_rule, LineHeightRule::Auto)
    || !paragraph_has_only_inline_drawing_content(paragraph)
    || paragraph.inlines.iter().any(|inline| {
      matches!(
        inline,
        InlineItem::Image(image)
          if image.placement == crate::docx::ImagePlacement::Inline
            && (image.inline_baseline_gap_pt.is_some()
              || image.line_box == crate::docx::InlineImageLineBox::OfficeMathExternal)
      )
    })
  {
    return spacing_after_pt;
  }

  let base_style = paragraph_base_line_style(paragraph);
  let line_gap_below_pt = if let Some(multiple) = paragraph
    .format
    .line_height_pt
    .filter(|multiple| *multiple > 1.0)
  {
    paragraph_single_line_height(paragraph, &base_style, text_metrics) * (multiple - 1.0)
  } else {
    let metrics = text_metrics.vertical_metrics(&base_style);
    // The object supplies the line ascent.  Of the paragraph mark's lower
    // half, Word retains the half-leading around the following text line and
    // lets only the ink descent overlap spacing-after.
    (metrics.descent_pt - metrics.leading_above_pt()).max(0.0)
  };

  // Word's modern WPS text story lets a drawing-only line own its ascent. Its
  // remaining lower line-box contribution is either the paragraph-mark's
  // ink descent below its half-leading or, for proportional auto spacing, the
  // proportional excess. That
  // lower gap and spacing-after occupy the same inter-paragraph region, so the
  // larger one wins rather than the two being added. tdf134784 (6 pt after)
  // and textbox-makeflyframe (zero after) are the positive and negative Office
  // fixed-output cases. Legacy mode 14, fixed/at-least line heights, and
  // explicitly baselined objects resolve their vertical extents separately.
  (spacing_after_pt - line_gap_below_pt).max(0.0)
}

fn inline_object_requires_flow_advance(
  y_pt: f32,
  object_line_height_pt: f32,
  content_bottom_pt: f32,
  page_has_body_content: bool,
) -> bool {
  page_has_body_content && y_pt + object_line_height_pt > content_bottom_pt + LAYOUT_EPSILON_PT
}

fn inline_text_height_for_text(
  style: &TextStyle,
  text: &str,
  text_metrics: &mut TextMetrics,
) -> f32 {
  text_metrics
    .line_vertical_metrics_for_text(text, style)
    .line_height_pt()
    .max(style.line_height_override_pt.unwrap_or_default())
}

#[derive(Clone, Copy, Debug)]
struct RubyMetrics {
  width_pt: f32,
  height_pt: f32,
  base_width_pt: f32,
  guide_width_pt: f32,
}

fn text_runs_width(runs: &[TextRun], text_metrics: &mut TextMetrics) -> f32 {
  runs
    .iter()
    .map(|run| text_metrics.measure_text(&run.text, &run.style))
    .sum()
}

fn text_runs_height(runs: &[TextRun], text_metrics: &mut TextMetrics) -> f32 {
  runs.iter().fold(0.0_f32, |height, run| {
    height.max(inline_text_height_for_text(
      &run.style,
      &run.text,
      text_metrics,
    ))
  })
}

fn ruby_inline_metrics(ruby: &RubyInline, text_metrics: &mut TextMetrics) -> RubyMetrics {
  let base_width_pt = text_runs_width(&ruby.base, text_metrics);
  let base_height_pt = text_runs_height(&ruby.base, text_metrics);
  if ruby.alignment == RubyAlignment::RightVertical {
    let mut guide_width_pt = 0.0_f32;
    let mut guide_height_pt = 0.0_f32;
    for run in &ruby.guide {
      for ch in run.text.chars() {
        let mut encoded = [0; 4];
        let text = ch.encode_utf8(&mut encoded);
        guide_width_pt = guide_width_pt.max(text_metrics.measure_text(text, &run.style));
        guide_height_pt += inline_text_height_for_text(&run.style, text, text_metrics);
      }
    }
    return RubyMetrics {
      width_pt: base_width_pt + guide_width_pt,
      height_pt: base_height_pt.max(guide_height_pt),
      base_width_pt,
      guide_width_pt,
    };
  }

  let guide_width_pt = text_runs_width(&ruby.guide, text_metrics);
  let guide_height_pt = text_runs_height(&ruby.guide, text_metrics);
  RubyMetrics {
    width_pt: base_width_pt.max(guide_width_pt),
    // ECMA-376 §17.3.3.12 defines hpsRaise as the guide baseline's
    // distance above the base text. The compound portion therefore needs
    // the normal text box plus that raised extent.
    height_pt: base_height_pt.max(guide_height_pt) + ruby.raise_pt.max(0.0),
    base_width_pt,
    guide_width_pt,
  }
}

fn ruby_line_height_for_flow(
  metrics: RubyMetrics,
  paragraph: &crate::docx::Paragraph,
  flow: FlowContext,
) -> f32 {
  document_grid_line_metrics(
    metrics.height_pt,
    paragraph,
    flow.setup,
    flow.text_segmentation,
  )
  .map_or(metrics.height_pt, |line_metrics| line_metrics.height_pt)
}

fn line_real_height(
  paragraph: &crate::docx::Paragraph,
  line_height: f32,
  line_index: usize,
  grid_auto_following_line_height_pt: Option<f32>,
  _has_content_control: bool,
) -> f32 {
  if let Some(height) = placeholder_floating_line_height(paragraph, line_height) {
    return height;
  }
  if line_index > 0
    && let Some(following_line_height_pt) = grid_auto_following_line_height_pt
  {
    return line_height.max(following_line_height_pt);
  }
  line_height
}

fn placeholder_floating_line_height(
  paragraph: &crate::docx::Paragraph,
  line_height: f32,
) -> Option<f32> {
  if !paragraph_has_behind_layout_in_cell_floating(paragraph) {
    return None;
  }
  let mut max_font_size: f32 = 0.0;
  let mut saw_text = false;
  for inline in &paragraph.inlines {
    let InlineItem::Text(run) = inline else {
      continue;
    };
    if !text_run_affects_line_height(&run.text) {
      continue;
    }
    if !run.preserve_text_portion {
      return None;
    }
    saw_text = true;
    max_font_size = max_font_size.max(effective_font_size_pt(&run.style, None));
  }
  saw_text
    .then(|| (max_font_size * LO_PLACEHOLDER_FLOATING_LINE_HEIGHT_PER_FONT_SIZE).min(line_height))
}

fn paragraph_has_behind_layout_in_cell_floating(paragraph: &crate::docx::Paragraph) -> bool {
  paragraph.inlines.iter().any(|inline| match inline {
    InlineItem::Image(image) => matches!(
      image.placement,
      crate::docx::ImagePlacement::Floating(placement)
        if placement.behind_text && placement.layout_in_cell
    ),
    InlineItem::Shape(shape) => matches!(
      shape.placement,
      crate::docx::ImagePlacement::Floating(placement)
        if placement.behind_text && placement.layout_in_cell
    ),
    _ => false,
  })
}

