  #[test]
  fn rotated_rounded_picture_clip_has_tighter_reflection_bounds_than_its_frame() {
    let rounded_rectangle = vec![
      common::PathCommand::MoveTo(common_point(20.0, 0.0)),
      common::PathCommand::LineTo(common_point(80.0, 0.0)),
      common::PathCommand::CubicTo {
        control1: common_point(91.0457, 0.0),
        control2: common_point(100.0, 8.9543),
        end: common_point(100.0, 20.0),
      },
      common::PathCommand::LineTo(common_point(100.0, 80.0)),
      common::PathCommand::CubicTo {
        control1: common_point(100.0, 91.0457),
        control2: common_point(91.0457, 100.0),
        end: common_point(80.0, 100.0),
      },
      common::PathCommand::LineTo(common_point(20.0, 100.0)),
      common::PathCommand::CubicTo {
        control1: common_point(8.9543, 100.0),
        control2: common_point(0.0, 91.0457),
        end: common_point(0.0, 80.0),
      },
      common::PathCommand::LineTo(common_point(0.0, 20.0)),
      common::PathCommand::CubicTo {
        control1: common_point(0.0, 8.9543),
        control2: common_point(8.9543, 0.0),
        end: common_point(20.0, 0.0),
      },
      common::PathCommand::Close,
    ];
    let unrotated = drawing_path_bounds(&rounded_rectangle).expect("unrotated bounds");
    assert_eq!(unrotated, common_rect(0.0, 0.0, 100.0, 100.0));

    let transform = Affine::translate((-50.0, -50.0))
      .then_rotate(30.0_f64.to_radians())
      .then_translate((50.0, 50.0).into());
    let rotated_commands =
      common::drawingml_geometry::transform_commands(rounded_rectangle, transform);
    let clipped = drawing_path_bounds(&rotated_commands).expect("rotated clip bounds");
    let frame = common::drawingml_geometry::transform_rect_bounds(
      KurboRect::new(0.0, 0.0, 100.0, 100.0),
      transform,
    );

    assert!(f64::from(clipped.origin.x.0) > frame.x0);
    assert!(f64::from(clipped.origin.y.0) > frame.y0);
    assert!(f64::from(clipped.origin.x.0 + clipped.size.width.0) < frame.x1);
    assert!(f64::from(clipped.origin.y.0 + clipped.size.height.0) < frame.y1);
  }

  #[test]
  fn word_text_effect_density_preserves_office_plain_shadow_boundary() {
    let below_boundary = wordprocessing_text_effect_max_pixels_per_point(
      None,
      Some(word_text_shadow(41_275.0 / 9_525.0)),
      None,
    );
    let at_boundary = wordprocessing_text_effect_max_pixels_per_point(
      None,
      Some(word_text_shadow(50_800.0 / 9_525.0)),
      None,
    );
    let mut transformed = word_text_shadow(190_500.0 / 9_525.0);
    transformed.scale_y = -0.3;
    transformed.skew_x_degrees = -13.34;
    let transformed =
      wordprocessing_text_effect_max_pixels_per_point(None, Some(transformed), None);

    assert!((below_boundary - 200.0 / 72.0).abs() < f32::EPSILON);
    assert!((at_boundary - 100.0 / 72.0).abs() < f32::EPSILON);
    assert!((transformed - 200.0 / 72.0).abs() < f32::EPSILON);
  }

  #[test]
  fn word_drawing_backdrop_density_tracks_direct2d_prescale_bands() {
    let samples = [
      // Sharp outer shadows remain at Word's 200-DPI base surface.
      (0.0, 200.0),
      // ptab/draw-shape-inline-effect and the 5-point picture shadow.
      (50_800.0 / 9_525.0, 100.0),
      (63_500.0 / 9_525.0, 100.0),
      // AlphaMod's 6-point and WPC_Shadow's 8-point shadows.
      (76_200.0 / 9_525.0, 200.0 / 3.0),
      (101_600.0 / 9_525.0, 200.0 / 3.0),
      // shape-effect-preservation's 9-point shadow.
      (114_300.0 / 9_525.0, 50.0),
    ];
    for (radius_px, expected_dpi) in samples {
      let actual = wordprocessing_drawing_backdrop_pixels_per_point(radius_px);
      assert!(
        (actual - expected_dpi / units::POINTS_PER_INCH).abs() < 0.0001,
        "radius={radius_px}, actual_dpi={}",
        actual * units::POINTS_PER_INCH
      );
    }

    // A foreground-modifying effect has no separated backdrop and therefore
    // keeps the 200-DPI surface rather than entering the blur prescaler.
    assert!(
      (wordprocessing_drawing_effect_max_pixels_per_point(None) - 200.0 / units::POINTS_PER_INCH)
        .abs()
        < f32::EPSILON
    );
  }

  #[test]
  fn word_text_effect_target_keeps_exact_origin_and_truncates_pixel_extent() {
    let target = wordprocessing_effect_bitmap_target(
      common::drawingml_image_effects::EffectOutputBounds {
        left_pt: -1.3,
        top_pt: 2.2,
        right_pt: 37.2,
        bottom_pt: 19.95,
      },
      common::drawingml_image_effects::EffectOutputBounds {
        left_pt: -7.5,
        top_pt: -4.0,
        right_pt: 45.0,
        bottom_pt: 25.0,
      },
      2.0,
      105,
      58,
    )
    .expect("positive Direct2D output target");

    // Microsoft's archived DirectX Postcard sample preserves the floating
    // GetImageLocalBounds origin, but static_cast<uint32> truncates the DIP
    // width and height after conversion to device pixels. A fractional crop
    // start therefore must not turn into an independently ceiled far edge.
    assert_eq!(
      target,
      WordprocessingEffectBitmapTarget {
        left_px: 12,
        top_px: 12,
        width_px: 77,
        height_px: 35,
      }
    );
  }

  #[test]
  fn word_text_effect_transport_keeps_straight_alpha_components() {
    let image = image::RgbaImage::from_pixel(1, 1, image::Rgba([146, 208, 80, 92]));

    let encoded = encode_wordprocessing_effect_bitmap_png(&image).unwrap();
    let decoded = image::load_from_memory_with_format(&encoded, image::ImageFormat::Png)
      .unwrap()
      .into_rgba8();

    // The PDF exporter owns the Direct2D premultiply/JPEG/black-Matte chain;
    // layout consumers receive the ordinary straight-alpha source.
    assert_eq!(decoded.get_pixel(0, 0).0, [146, 208, 80, 92]);
  }

