  #[test]
  fn paragraph_frame_wrap_uses_around_spacing_and_blocks_none_not_beside() {
    let setup = PageSetup {
      width_pt: 612.0,
      ..PageSetup::default()
    };
    let bounds = FrameBounds {
      x_pt: 200.0,
      y_pt: 80.0,
      width_pt: 100.0,
      height_pt: 40.0,
    };
    let placement = FloatingFramePlacement {
      wrap: FrameWrapMode::Around,
      margin_top_pt: 8.0,
      margin_right_pt: 12.0,
      margin_bottom_pt: 16.0,
      margin_left_pt: 10.0,
      ..Default::default()
    };
    let mut page = empty_page(setup, 0);

    append_paragraph_frame_wrap_exclusion(
      &mut page,
      placement,
      bounds,
      HorizontalFrameOutsets::default(),
    );

    let [around] = page.wrap_exclusions.as_slice() else {
      panic!("one paragraph-frame exclusion");
    };
    assert_eq!(
      (
        around.left_pt,
        around.right_pt,
        around.top_pt,
        around.bottom_pt,
      ),
      (190.0, 312.0, 72.0, 136.0)
    );
    assert!(!around.blocks_flow);
    assert_eq!(around.owner, WrapExclusionOwner::ParagraphFrame);
    assert_eq!(
      dodge_text_wrap_exclusions(80.0, 12.0, 72.0, 540.0, page.wrap_exclusions.as_slice()),
      80.0
    );

    let paragraph_border = BorderStyle {
      width_pt: 0.75,
      spacing_pt: 1.0,
      ..BorderStyle::default()
    };
    let border_outset = paragraph_decoration_horizontal_outset(Some(paragraph_border), false);
    assert_eq!(border_outset, 3.25);
    page.wrap_exclusions.clear();
    append_paragraph_frame_wrap_exclusion(
      &mut page,
      placement,
      bounds,
      HorizontalFrameOutsets {
        left_pt: border_outset,
        right_pt: border_outset,
      },
    );
    let [bordered] = page.wrap_exclusions.as_slice() else {
      panic!("one bordered paragraph-frame exclusion");
    };
    assert_eq!((bordered.left_pt, bordered.right_pt), (186.75, 315.25));

    for wrap in [FrameWrapMode::None, FrameWrapMode::NotBeside] {
      page.wrap_exclusions.clear();
      append_paragraph_frame_wrap_exclusion(
        &mut page,
        FloatingFramePlacement { wrap, ..placement },
        bounds,
        HorizontalFrameOutsets::default(),
      );
      let [blocking] = page.wrap_exclusions.as_slice() else {
        panic!("one blocking paragraph-frame exclusion");
      };
      assert_eq!((blocking.left_pt, blocking.right_pt), (0.0, 612.0));
      assert!(blocking.blocks_flow);
      assert_eq!(
        dodge_text_wrap_exclusions(80.0, 12.0, 72.0, 540.0, page.wrap_exclusions.as_slice(),),
        136.0
      );
    }

    page.wrap_exclusions.clear();
    append_paragraph_frame_wrap_exclusion(
      &mut page,
      FloatingFramePlacement {
        wrap: FrameWrapMode::Tight,
        ..placement
      },
      bounds,
      HorizontalFrameOutsets::default(),
    );
    let [tight] = page.wrap_exclusions.as_slice() else {
      panic!("one tight paragraph-frame exclusion");
    };
    assert_eq!((tight.left_pt, tight.right_pt), (200.0, 300.0));
    assert_eq!((tight.top_pt, tight.bottom_pt), (72.0, 136.0));
  }

  #[test]
  fn both_sides_wrap_exposes_left_then_right_segments_on_one_line() {
    let exclusion = WrapExclusion {
      left_pt: 100.0,
      right_pt: 200.0,
      top_pt: 72.0,
      bottom_pt: 120.0,
      side: ImageWrapSide::BothSides,
      blocks_flow: false,
      uses_contour: false,
      owner: WrapExclusionOwner::Drawing,
    };

    assert_eq!(
      line_bounds_for_y(36.0, 300.0, 80.0, 12.0, &[exclusion]),
      (36.0, 100.0)
    );
    assert_eq!(
      next_wrap_line_segment_for_y(36.0, 300.0, 80.0, 12.0, 100.0, &[exclusion]),
      Some((200.0, 300.0))
    );

    let largest = WrapExclusion {
      side: ImageWrapSide::Largest,
      ..exclusion
    };
    assert_eq!(
      line_bounds_for_y(36.0, 300.0, 80.0, 12.0, &[largest]),
      (200.0, 300.0)
    );
    assert_eq!(
      next_wrap_line_segment_for_y(36.0, 300.0, 80.0, 12.0, 300.0, &[largest]),
      None
    );
  }

  #[test]
  fn word_upper_margin_moves_drawing_but_preserves_floating_table_side_wrap() {
    let side_wrapped = WrapExclusion {
      left_pt: 300.0,
      right_pt: 420.0,
      top_pt: 96.0,
      bottom_pt: 112.0,
      side: ImageWrapSide::BothSides,
      blocks_flow: false,
      uses_contour: false,
      owner: WrapExclusionOwner::FloatingTable,
    };
    assert_eq!(
      shift_first_line_below_upper_margin_exclusions(100.0, 6.0, 72.0, 540.0, &[side_wrapped],),
      100.0
    );

    let full_width = WrapExclusion {
      left_pt: 70.0,
      right_pt: 542.0,
      ..side_wrapped
    };
    assert_eq!(
      shift_first_line_below_upper_margin_exclusions(100.0, 6.0, 72.0, 540.0, &[full_width]),
      112.0
    );

    let margin_only = WrapExclusion {
      bottom_pt: 99.0,
      ..full_width
    };
    assert_eq!(
      shift_first_line_below_upper_margin_exclusions(100.0, 6.0, 72.0, 540.0, &[margin_only]),
      100.0
    );

    let side_wrapped_drawing = WrapExclusion {
      owner: WrapExclusionOwner::Drawing,
      ..side_wrapped
    };
    assert_eq!(
      shift_first_line_below_upper_margin_exclusions(
        100.0,
        6.0,
        72.0,
        540.0,
        &[side_wrapped_drawing],
      ),
      118.0
    );

    let side_wrapped_contour = WrapExclusion {
      uses_contour: true,
      ..side_wrapped_drawing
    };
    assert_eq!(
      shift_first_line_below_upper_margin_exclusions(
        100.0,
        6.0,
        72.0,
        540.0,
        &[side_wrapped_contour],
      ),
      100.0
    );

    let full_width_drawing = WrapExclusion {
      owner: WrapExclusionOwner::Drawing,
      ..full_width
    };
    assert_eq!(
      shift_first_line_below_upper_margin_exclusions(
        100.0,
        6.0,
        72.0,
        540.0,
        &[full_width_drawing],
      ),
      118.0
    );
  }

