  #[test]
  fn drawingml_relative_height_orders_the_foreground_drawing_layer() {
    let floating = |id: f32, value: u32, behind_text: bool| PageItem::FloatingDrawing {
      items: vec![PageItem::Rect(RectItem {
        x_pt: id,
        y_pt: 0.0,
        width_pt: 1.0,
        height_pt: 1.0,
        fill_color: None,
        fill_opacity: 1.0,
        stroke: None,
        stroke_opacity: 1.0,
      })],
      paint_order: FloatingPaintOrder::DrawingMlRelativeHeight(value),
      behind_text,
    };
    let body = PageItem::Rect(RectItem {
      x_pt: 100.0,
      y_pt: 0.0,
      width_pt: 1.0,
      height_pt: 1.0,
      fill_color: None,
      fill_opacity: 1.0,
      stroke: None,
      stroke_opacity: 1.0,
    });
    let mut items = vec![
      floating(9.0, 9, false),
      body,
      floating(2.0, 2, false),
      floating(-1.0, 4, true),
    ];

    order_floating_page_items(&mut items, None, false, 12);

    let ids = items
      .iter()
      .map(|item| match item {
        PageItem::Rect(rect) => rect.x_pt,
        PageItem::FloatingDrawing { items, .. } => {
          let PageItem::Rect(rect) = &items[0] else {
            panic!("expected drawing marker");
          };
          rect.x_pt
        }
        _ => panic!("unexpected page item"),
      })
      .collect::<Vec<_>>();
    assert_eq!(ids, vec![-1.0, 100.0, 2.0, 9.0]);
  }

  #[test]
  fn floating_paint_order_remaps_text_ranges_without_swallowing_body_frames() {
    let marker = |x_pt| {
      PageItem::Rect(RectItem {
        x_pt,
        y_pt: 0.0,
        width_pt: 1.0,
        height_pt: 1.0,
        fill_color: None,
        fill_opacity: 1.0,
        stroke: None,
        stroke_opacity: 1.0,
      })
    };
    let mut items = vec![
      marker(10.0),
      marker(20.0),
      PageItem::FloatingDrawing {
        items: vec![marker(30.0)],
        paint_order: FloatingPaintOrder::DrawingMlRelativeHeight(2),
        behind_text: true,
      },
    ];

    let order = order_floating_page_items(&mut items, None, false, 12);

    assert_eq!(order.old_to_new, vec![1, 2, 0]);
    assert_eq!(order.remap_range(0, 1), (1, 2));
    assert_eq!(
      order.remap_range(1, 3),
      (2, 3),
      "the anchor frame should retain its body item without owning the detached drawing"
    );
    assert_eq!(
      order.remap_range(2, 3),
      (0, 1),
      "a drawing-only frame still keeps a usable range"
    );
  }

  #[test]
  fn drawingml_relative_height_preserves_legacy_sentinels_and_modern_unsigned_order() {
    const MAX_DRAWINGML_RELATIVE_HEIGHT: u32 = 0x1dff_ffff;
    let legacy_maximum = floating_paint_order_key(
      FloatingPaintOrder::DrawingMlRelativeHeight(MAX_DRAWINGML_RELATIVE_HEIGHT),
      12,
    );

    assert_eq!(
      floating_paint_order_key(FloatingPaintOrder::DrawingMlRelativeHeight(0), 12),
      legacy_maximum
    );
    assert_eq!(
      floating_paint_order_key(FloatingPaintOrder::DrawingMlRelativeHeight(1), 12),
      legacy_maximum
    );
    assert_eq!(
      floating_paint_order_key(
        FloatingPaintOrder::DrawingMlRelativeHeight(MAX_DRAWINGML_RELATIVE_HEIGHT + 1),
        12,
      ),
      legacy_maximum
    );
    assert!(
      floating_paint_order_key(FloatingPaintOrder::DrawingMlRelativeHeight(2), 12) < legacy_maximum
    );

    let modern_zero = floating_paint_order_key(FloatingPaintOrder::DrawingMlRelativeHeight(0), 15);
    let modern_one = floating_paint_order_key(FloatingPaintOrder::DrawingMlRelativeHeight(1), 15);
    let modern_peer =
      floating_paint_order_key(FloatingPaintOrder::DrawingMlRelativeHeight(0x0f00_0000), 15);
    let modern_above_legacy_max = floating_paint_order_key(
      FloatingPaintOrder::DrawingMlRelativeHeight(MAX_DRAWINGML_RELATIVE_HEIGHT + 1),
      15,
    );
    assert!(modern_zero < modern_one);
    assert!(modern_one < modern_peer);
    assert!(modern_peer < modern_above_legacy_max);
    assert!(
      floating_paint_order_key(FloatingPaintOrder::VmlZIndex(i32::MIN), 15)
        > modern_above_legacy_max
    );
  }

